
'use strict';
const LOGO='data:image/png;base64,';
const KEY='erics-billing-v1', uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2), today=()=>new Date().toLocaleDateString('en-CA'),addDays=(n)=>{let d=new Date();d.setDate(d.getDate()+n);return d.toLocaleDateString('en-CA')},esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>Number(n)||0,round=n=>Math.round((n+Number.EPSILON)*100)/100,money=n=>'₹'+Number(n).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const catalog=[['Web Development','Fast, responsive, mobile-first websites with seamless user experiences.',0],['E-commerce Website','Online stores with payment gateways, product catalogs, and optimized buying journeys.',0],['Digital Marketing','Multi-channel campaign strategy, execution, and performance reporting.',25000],['SEO (Search Engine Optimization)','Keyword research, on-page optimization, technical SEO, and organic traffic growth.',30000],['Full Stack Development','End-to-end web applications, custom APIs, authentication, and database design.',0],['AI Automation','Workflow automation, lead generation funnels, and AI chatbot integrations.',40000],['WhatsApp Automation Setup','Messaging flows, broadcast campaigns, lead qualification, and CRM integration.',0],['Brand Solution','Logo marks, color palettes, typography guidelines, and brand identity systems.',15000],['Creative Designing','Social media carousels, marketing banners, and campaign assets.',0],['AI Product Video Generation','AI-generated product advertisements with camera paths, lighting, and audio.',0],['Content Writing','Landing pages, ad copy, email campaigns, and pitch decks.',0],['Property Management (Online Inventory Management)','Inventory control, unit booking, availability tracking, and stock logs.',0],['Digital Portfolio','Portfolio websites to showcase work and convert prospective clients.',15000],['Logo Design','Logo design with usage variations and export formats.',15000],['AI Automation Retainer','Monthly maintenance and support for automation workflows.',15000]].map(([name,description,rate])=>({id:uid(),name,description,rate}));
const quoteTerms='50% advance payment is required to commence work; balance due upon project completion.\nPricing excludes third-party costs such as domain registration, hosting, and paid ad spend unless stated otherwise.\nProject timelines will be confirmed upon written acceptance of this quotation.\nRevisions beyond the agreed scope may be billed separately.';
const defaults={version:1,documents:[],clients:[],services:catalog,settings:{name:"Eric's Designs",tagline:'Creative & Digital Marketing Agency',address:'Mumbai, Maharashtra, India',email:'ericdesignsindia@gmail.com',phone:'+91 79941 60369',gstin:'',account:'',bank:'',accountNo:'',ifsc:'',upi:'',tax:18,quoteTerms,invoiceTerms:"Thank you for choosing Eric's Designs. Payment is due within 7 days of the invoice date."}};
let db;try{db=JSON.parse(localStorage.getItem(KEY))||structuredClone(defaults)}catch{db=structuredClone(defaults);setTimeout(()=>toast('Saved data could not be read. Restore a backup before saving new work.'),500)}let view='Overview',draft=null,previewDoc=null,filter='',query='';
let lastSnapshot=localStorage.getItem(KEY);
function persist(){try{if(localStorage.getItem(KEY)!==lastSnapshot){toast('Another tab changed your records. Reload before saving.');return false}let serialized=JSON.stringify(db);localStorage.setItem(KEY,serialized);lastSnapshot=serialized;return true}catch{toast('Unable to save. Browser storage may be full or disabled. Export a backup now.');return false}}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.add('hidden'),4200)}
function totals(d){const subtotal=round(d.items.reduce((s,i)=>s+round(num(i.qty)*num(i.rate)),0));const discount=round(subtotal*num(d.discount)/100),net=round(subtotal-discount),tax=round(net*num(d.tax)/100),total=round(net+tax),paid=round((d.payments||[]).reduce((s,p)=>s+num(p.amount),0));return{subtotal,discount,tax,total,paid,balance:round(total-paid)}}
function status(d){if(d.type==='Quotation')return d.status;if(d.status==='Cancelled')return 'Cancelled';let t=totals(d);if(t.balance<=0&&t.total>0)return 'Paid';if(d.status==='Draft')return 'Draft';if(d.due<today()&&t.balance>0)return 'Overdue';return t.paid>0?'Part paid':d.status}
function nav(v){if(draft&&!confirm('Leave this document? Unsaved changes will be lost.'))return;draft=null;view=v;query='';filter='';render()}
function pageHeader(title,buttons='',subtitle=''){return `<header><div><div class="eyebrow">Eric's Designs / ${esc(view)}</div><h1>${title}</h1>${subtitle?`<p class="sub">${subtitle}</p>`:''}</div><div class="actions">${buttons}</div></header>`}
function render(){document.getElementById('nav').innerHTML=['Overview','Quotations','Invoices','Clients','Services','Settings'].map(v=>`<button class="${view===v?'active':''}" onclick="nav('${v}')">${v}</button>`).join('');document.getElementById('app').innerHTML=draft?editor():view==='Settings'?settings():view==='Services'?services():view==='Clients'?clients():listing();if(draft)updateTotal()}
function listing(){const invoices=db.documents.filter(d=>d.type==='Invoice'&&d.status!=='Cancelled');const unpaid=invoices.filter(d=>d.status!=='Draft').reduce((s,d)=>s+Math.max(0,totals(d).balance),0),paid=invoices.reduce((s,d)=>s+totals(d).paid,0);return pageHeader(view==='Overview'?'Your business, in order.':view,`<button onclick="newDoc('Quotation')">+ New quotation</button><button class="primary" onclick="newDoc('Invoice')">+ New invoice</button>`,'Create, track, and send beautifully clear documents.')+`<div class="stats"><div class="stat"><span>Outstanding invoices</span><strong>${money(unpaid)}</strong></div><div class="stat"><span>Payments received</span><strong>${money(paid)}</strong></div><div class="stat"><span>Quotations created</span><strong>${db.documents.filter(d=>d.type==='Quotation').length}</strong></div></div><section class="panel"><h2>${view==='Overview'?'Recent documents':view}</h2><div class="toolbar"><input aria-label="Search documents" placeholder="Search client, project, or document number…" oninput="query=this.value;renderRows()"><select style="width:175px" aria-label="Filter status" onchange="filter=this.value;renderRows()"><option value="">All statuses</option>${['Draft','Sent','Accepted','Declined','Paid','Part paid','Overdue','Cancelled'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="rows">${rows()}</div></section>`}
function rows(){let docs=db.documents.filter(d=>(view==='Overview'||d.type===(view==='Invoices'?'Invoice':'Quotation'))&&(!filter||status(d)===filter)&&[d.number,d.client.name,d.project].join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.updated.localeCompare(a.updated));return docs.length?`<div class="tablewrap"><table><thead><tr><th>Document</th><th>Client / project</th><th>Date</th><th>Status</th><th class="right">Total</th><th>Actions</th></tr></thead><tbody>${docs.map(d=>`<tr><td><b>${esc(d.number)}</b><small>${d.type}</small></td><td>${esc(d.client.name)}<small>${esc(d.project)}</small></td><td>${esc(d.date)}</td><td><span class="badge ${status(d)}">${status(d)}</span></td><td class="right">${money(totals(d).total)}</td><td><div class="actions"><button onclick="openDoc('${d.id}')">Edit</button><button onclick="showPreview('${d.id}')">Preview</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="eyebrow">A little less admin</div><h2>${db.documents.length?'No matching documents':'Your next project starts here.'}</h2><p>${db.documents.length?'Try another search or status.':'Create a quotation, agree the scope, then turn it into an invoice.'}</p><button class="gold" onclick="newDoc('Quotation')">Create a quotation</button></div>`}
function renderRows(){document.getElementById('rows').innerHTML=rows()}
function nextNumber(type){let prefix=type==='Invoice'?'ED-':'ED-Q-';let n=1;while(db.documents.some(d=>d.number===prefix+String(n).padStart(4,'0')))n++;return prefix+String(n).padStart(4,'0')}
function newDoc(type){if(draft&&!confirm('Discard unsaved changes?'))return;draft={id:uid(),type,number:nextNumber(type),date:today(),due:addDays(type==='Invoice'?7:30),project:'',client:{name:'',contact:'',email:'',phone:'',address:'',gstin:''},items:[{name:'',description:'',qty:1,rate:0}],discount:0,tax:db.settings.tax,status:'Draft',terms:type==='Invoice'?db.settings.invoiceTerms:db.settings.quoteTerms,payments:[],business:structuredClone(db.settings),updated:new Date().toISOString()};view=type==='Invoice'?'Invoices':'Quotations';render()}
function openDoc(id){draft=structuredClone(db.documents.find(d=>d.id===id));view=draft.type==='Invoice'?'Invoices':'Quotations';render()}
function field(label,key,value,type='text',extra=''){return `<div class="field"><label for="${key}">${label}</label><input id="${key}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function df(label,key,type='text',extra=''){return field(label,key,draft[key],type,`oninput="draft.${key}=this.value;updateTotal()" ${extra}`)}
function editor(){return pageHeader(`${draft.type} <span style="color:#949985">${esc(draft.number)}</span>`,`<button onclick="cancelEdit()">Back</button><button onclick="previewDraft()">Preview</button><button class="primary" onclick="saveDoc()">Save ${draft.type.toLowerCase()}</button>`)+`<div class="editor"><div class="stack"><section class="panel"><h2>Document details</h2><div class="grid three">${df('Document number','number','text','required')}${df('Issue date','date','date','required')}${df(draft.type==='Invoice'?'Payment due':'Valid until','due','date','required')}${df('Project / campaign','project')}<div><label for="state">Status</label><select id="state" onchange="draft.status=this.value">${(draft.type==='Invoice'?['Draft','Sent','Cancelled']:['Draft','Sent','Accepted','Declined','Cancelled']).map(s=>`<option ${draft.status===s?'selected':''}>${s}</option>`).join('')}</select></div></div></section><section class="panel"><div class="actions" style="justify-content:space-between;margin-bottom:20px"><h2 style="margin:0">Bill to</h2><select aria-label="Use saved client" style="width:220px" onchange="useClient(this.value)"><option value="">Use a saved client</option>${db.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="grid">${Object.entries({name:'Client / company *',contact:'Contact person',email:'Email',phone:'Phone',address:'Address',gstin:'Client GSTIN (optional)'}).map(([k,l])=>field(l,'client-'+k,draft.client[k],k==='email'?'email':'text',`oninput="draft.client.${k}=this.value" ${k==='name'?'required':''}`)).join('')}</div><p class="hint">The client is saved to your client list when you save the document.</p></section><section class="panel"><h2>Services & scope</h2><select aria-label="Add service from catalog" onchange="addService(this.value)"><option value="">+ Add from service catalog</option>${db.services.map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.rate?money(s.rate):'Set price'}</option>`).join('')}</select><div id="items">${items()}</div><button style="margin-top:18px" onclick="draft.items.push({name:'',description:'',qty:1,rate:0});refreshItems()">+ Custom line item</button></section><section class="panel"><h2>Terms & notes</h2><label for="terms">Shown on the document</label><textarea id="terms" style="min-height:145px" oninput="draft.terms=this.value">${esc(draft.terms)}</textarea></section>${draft.type==='Invoice'?payments():''}<div class="actions">${db.documents.some(d=>d.id===draft.id)?`<button onclick="duplicateDoc()">Duplicate</button>${draft.type==='Quotation'?'<button onclick="convertDoc()">Convert to invoice</button>':''}<button class="danger" onclick="deleteDoc()">Delete document</button>`:''}</div></div><div class="stack"><section class="panel summary"><div class="eyebrow">At a glance</div><h2>Document total</h2><div class="grid">${df('Discount %','discount','number','min="0" max="100" step="0.01"')}${df('GST / tax %','tax','number','min="0" max="100" step="0.01"')}</div><p class="hint">Tax is applied after discount. Set to 0 when it does not apply.</p><div id="total"></div><p class="hint">All amounts in INR. Rates of ₹0 must be updated before saving.</p></section><section class="panel"><h3>Ready for your client</h3><p class="sub">Preview your document, then choose Print / Save PDF to download a clean A4 copy.</p><p class="hint">Changes are saved when you click Save. Email delivery is manual.</p></section></div></div>`}
function items(){return draft.items.map((i,n)=>`<div class="lineitem"><div><label for="name${n}">Service ${n+1}</label><input id="name${n}" value="${esc(i.name)}" placeholder="Service name" oninput="draft.items[${n}].name=this.value"><textarea aria-label="Service ${n+1} description" placeholder="Scope, deliverables, timeline…" oninput="draft.items[${n}].description=this.value">${esc(i.description)}</textarea></div><div><label for="qty${n}">Qty</label><input id="qty${n}" type="number" min="0.01" step="0.01" value="${i.qty}" oninput="draft.items[${n}].qty=num(this.value);updateTotal()"></div><div><label for="rate${n}">Rate ₹</label><input id="rate${n}" type="number" min="0.01" step="0.01" value="${i.rate}" oninput="draft.items[${n}].rate=num(this.value);updateTotal()"><div class="hint" id="lineTotal${n}">${money(i.qty*i.rate)}</div></div><div><label>&nbsp;</label><button aria-label="Remove service ${n+1}" onclick="draft.items.splice(${n},1);refreshItems()">×</button></div></div>`).join('')}
function refreshItems(){document.getElementById('items').innerHTML=items();updateTotal()}
function addService(id){let s=db.services.find(s=>s.id===id);if(!s)return;let i={name:s.name,description:s.description,qty:1,rate:s.rate};if(draft.items.length===1&&!draft.items[0].name)draft.items=[i];else draft.items.push(i);render()}
function useClient(id){let c=db.clients.find(c=>c.id===id);if(c){draft.client=structuredClone(c);render()}}
function updateTotal(){if(!draft)return;let t=totals(draft);document.getElementById('total').innerHTML=`<div class="totalrow"><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div class="totalrow"><span>Discount</span><span>−${money(t.discount)}</span></div><div class="totalrow"><span>GST / tax (${num(draft.tax)}%)</span><span>${money(t.tax)}</span></div><div class="totalrow big"><span>Total</span><span>${money(t.total)}</span></div>${draft.type==='Invoice'?`<div class="totalrow"><span>Paid</span><span>${money(t.paid)}</span></div><div class="totalrow"><b>Balance due</b><b>${money(t.balance)}</b></div>`:`<div class="totalrow"><span>50% advance</span><span>${money(round(t.total/2))}</span></div>`}`;draft.items.forEach((i,n)=>{let el=document.getElementById('lineTotal'+n);if(el)el.textContent=money(round(i.qty*i.rate))})}
function valid(){if(!draft.client.name.trim())return 'Enter the client or company name.';if(!draft.number.trim())return 'Enter a document number.';if(db.documents.some(d=>d.id!==draft.id&&d.number===draft.number.trim()))return 'This document number already exists.';if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.date)||!/^\d{4}-\d{2}-\d{2}$/.test(draft.due)||draft.due<draft.date)return 'Choose valid dates; the due date must be on or after the issue date.';if(draft.client.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(draft.client.email))return 'Enter a valid client email address.';if(!draft.items.length||draft.items.some(i=>!i.name.trim()||!Number.isFinite(+i.qty)||+i.qty<=0||!Number.isFinite(+i.rate)||+i.rate<=0))return 'Every service needs a name, quantity, and price greater than zero.';if([draft.discount,draft.tax].some(v=>!Number.isFinite(+v)||+v<0||+v>100))return 'Discount and tax must be between 0 and 100.';if(totals(draft).paid>totals(draft).total)return 'Payments exceed the total. Adjust the document or payments.';return ''}
function saveDoc(quiet=false){let e=valid();if(e){toast(e);return false}draft.number=draft.number.trim();draft.updated=new Date().toISOString();let before=structuredClone(db),i=db.documents.findIndex(d=>d.id===draft.id);if(i<0)db.documents.push(structuredClone(draft));else db.documents[i]=structuredClone(draft);let ci=db.clients.findIndex(c=>c.id===draft.client.id||c.name.toLowerCase()===draft.client.name.trim().toLowerCase());let c={...(ci>=0?db.clients[ci]:{}),...draft.client,name:draft.client.name.trim(),id:ci>=0?db.clients[ci].id:uid()};if(ci>=0)db.clients[ci]=c;else db.clients.push(c);draft.client.id=c.id;let savedDoc=db.documents.find(d=>d.id===draft.id);if(savedDoc)savedDoc.client.id=c.id;if(!persist()){db=before;return false}if(!quiet){draft=null;render();toast('Document saved')}return true}
function cancelEdit(){if(confirm('Leave this document? Unsaved changes will be lost.')){draft=null;render()}}
function deleteDoc(){if(!confirm('Permanently delete this document from this browser?'))return;const old=db.documents;db.documents=db.documents.filter(d=>d.id!==draft.id);if(!persist()){db.documents=old;return}draft=null;render();toast('Document deleted')}
function duplicateDoc(){draft.id=uid();draft.number=nextNumber(draft.type);draft.status='Draft';draft.payments=[];draft.date=today();draft.due=addDays(draft.type==='Invoice'?7:30);delete draft.sourceId;render();toast('Duplicate ready. Review and save.')}
function convertDoc(){if(!saveDoc(true))return;let source=draft.id,existing=db.documents.find(d=>d.sourceId===source);if(existing){openDoc(existing.id);toast('Opened the invoice already created from this quotation.');return}draft=structuredClone(draft);draft.sourceId=source;draft.id=uid();draft.type='Invoice';draft.number=nextNumber('Invoice');draft.date=today();draft.due=addDays(7);draft.status='Draft';draft.payments=[];draft.terms=db.settings.invoiceTerms;view='Invoices';render();toast('Invoice prepared from quotation. Review and save.')}
function payments(){return `<section class="panel"><h2>Payment history</h2>${draft.payments.length?draft.payments.map((p,n)=>`<div class="totalrow"><span>${esc(p.date)} · ${esc(p.reference||'Payment')}</span><b>${money(p.amount)}</b><button class="danger" onclick="draft.payments.splice(${n},1);render()">Remove</button></div>`).join(''):'<p class="sub">No payments recorded.</p>'}<div class="grid three">${field('Date','payDate',today(),'date')}${field('Amount ₹','payAmount','','number','min="0.01" step="0.01"')}${field('Reference / method','payRef','')}</div><button style="margin-top:15px" onclick="addPayment()">Record payment</button><p class="hint">Save the invoice to retain payment changes.</p></section>`}
function addPayment(){let amount=num(document.getElementById('payAmount').value),date=document.getElementById('payDate').value;if(amount<=0||!date||amount>totals(draft).balance){toast('Enter a payment date and amount within the outstanding balance.');return}draft.payments.push({id:uid(),date,amount:round(amount),reference:document.getElementById('payRef').value});if(draft.status==='Draft')draft.status='Sent';render()}
function documentHTML(d){let b=d.business||db.settings,t=totals(d),invoice=d.type==='Invoice';return `<article class="document"><div class="dochead"><div><img class="doclogo" src="${LOGO}" alt="Eric’s Designs logo"><div class="docbrand">${esc(b.name).toUpperCase()}</div><small>${esc(b.tagline)}<br>${esc(b.address)}</small></div><div><h2>${d.type}</h2><small>${esc(d.number)}${d.status==='Draft'?' · DRAFT':''}${d.status==='Cancelled'?' · CANCELLED':''}</small></div></div><div class="docmeta"><div><h3>${invoice?'BILL TO':'PREPARED FOR'}</h3><b>${esc(d.client.name)}</b><br>${[d.client.contact,d.client.address,d.client.email,d.client.phone,d.client.gstin?'GSTIN: '+d.client.gstin:''].filter(Boolean).map(esc).join('<br>')}</div><div><h3>DETAILS</h3>Issue date: ${esc(d.date)}<br>${invoice?'Due date':'Valid until'}: ${esc(d.due)}<br>Project: ${esc(d.project||'—')}${b.gstin?'<br>GSTIN: '+esc(b.gstin):''}</div></div><h3>${invoice?'SERVICES PROVIDED':'SERVICES QUOTED'}</h3><table><thead><tr><th>#</th><th>Service / description</th><th class="right">Qty</th><th class="right">Rate (₹)</th><th class="right">Amount (₹)</th></tr></thead><tbody>${d.items.map((i,n)=>`<tr><td>${n+1}</td><td><b>${esc(i.name)}</b><small>${esc(i.description)}</small></td><td class="right">${num(i.qty)}</td><td class="right">${money(i.rate)}</td><td class="right">${money(round(i.qty*i.rate))}</td></tr>`).join('')}</tbody></table><div class="doctotals"><div class="totalrow"><span>Subtotal</span><span>${money(t.subtotal)}</span></div>${t.discount?`<div class="totalrow"><span>Discount (${num(d.discount)}%)</span><span>−${money(t.discount)}</span></div>`:''}<div class="totalrow"><span>GST / tax (${num(d.tax)}%)</span><span>${money(t.tax)}</span></div><div class="totalrow big"><span>TOTAL</span><span>${money(t.total)}</span></div>${invoice?`<div class="totalrow"><span>Paid</span><span>${money(t.paid)}</span></div><div class="totalrow"><b>BALANCE DUE</b><b>${money(t.balance)}</b></div>`:''}</div>${invoice&&[b.account,b.bank,b.accountNo,b.ifsc,b.upi].some(Boolean)?`<div class="docnotes"><h3>PAYMENT DETAILS</h3>${[['Account name',b.account],['Bank & branch',b.bank],['Account no.',b.accountNo],['IFSC',b.ifsc],['UPI',b.upi]].filter(x=>x[1]).map(([k,v])=>esc(k)+': '+esc(v)).join('\n')}</div>`:''}<div class="docnotes"><h3>${invoice?'NOTES':'TERMS & CONDITIONS'}</h3>${!invoice?'This quotation is valid until '+esc(d.due)+'.\n':''}${esc(d.terms)}</div><div class="docfooter">${invoice?'Thank you for choosing':'Thank you for considering'} ${esc(b.name)}.<br>${esc(b.email)} · ${esc(b.phone)}</div></article>`}
function showPreview(id){previewDoc=structuredClone(db.documents.find(d=>d.id===id));document.getElementById('previewBody').innerHTML=documentHTML(previewDoc);document.getElementById('preview').showModal()}
function previewDraft(){let e=valid();if(e){toast(e);return}previewDoc=structuredClone(draft);document.getElementById('previewBody').innerHTML=documentHTML(previewDoc);document.getElementById('preview').showModal()}
function printDoc(){document.getElementById('printArea').innerHTML=documentHTML(previewDoc);let title=document.title;document.title=previewDoc.number+' - '+previewDoc.client.name;window.print();document.title=title}
function clients(){return pageHeader('Your client directory','', 'Clients are added automatically when you save a document.')+`<section class="panel">${db.clients.length?`<div class="tablewrap"><table><thead><tr><th>Client</th><th>Contact</th><th>Email</th><th>Phone</th><th></th></tr></thead><tbody>${db.clients.map(c=>`<tr><td><b>${esc(c.name)}</b><small>${esc(c.address)}</small></td><td>${esc(c.contact)}</td><td>${esc(c.email)}</td><td>${esc(c.phone)}</td><td><button onclick="newForClient('${c.id}')">New quotation</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>A home for your clients.</h2><p>Save your first quotation or invoice to add a client.</p><button onclick="newDoc(\'Quotation\')">Create quotation</button></div>'}</section>`}
function newForClient(id){newDoc('Quotation');useClient(id)}
function services(){return pageHeader('A service for every brief.','','13 services from your catalog, plus logo design and the automation retainer from your quotation. Rates are editable defaults.')+`<div class="catalog">${db.services.map((s,i)=>`<section class="panel service"><div class="eyebrow">${String(i+1).padStart(2,'0')}</div><h2>${esc(s.name)}</h2><p>${esc(s.description)}</p><label for="service-${s.id}">Default rate · INR</label><input id="service-${s.id}" type="number" min="0" step="0.01" value="${s.rate}" onchange="setRate('${s.id}',this)"><span class="hint">${s.rate?'Reference rate; adjust for each project.':'Set the price for each project.'}</span></section>`).join('')}</div>`}
function setRate(id,input){let v=Number(input.value);if(!Number.isFinite(v)||v<0){toast('Enter a valid non-negative rate.');return}let s=db.services.find(s=>s.id===id),old=s.rate;s.rate=round(v);if(persist())toast('Default rate saved');else{s.rate=old;input.value=old}}
function settings(){return pageHeader('Studio settings',`<button class="primary" onclick="saveSettings()">Save settings</button>`,'Business details are copied into new documents. Existing documents keep their original details.')+`<div class="stack"><section class="panel"><h2>Business profile</h2><div class="grid">${Object.entries({name:'Business name',tagline:'Tagline',address:'Address',email:'Email',phone:'Phone',gstin:'GSTIN (optional)',tax:'Default GST / tax %'}).map(([k,l])=>field(l,'set-'+k,db.settings[k],k==='tax'?'number':k==='email'?'email':'text',k==='tax'?'min="0" max="100"':'')).join('')}</div></section><section class="panel"><h2>Payment details</h2><p class="sub">Only completed fields appear on invoices.</p><div class="grid">${Object.entries({account:'Account holder',bank:'Bank & branch',accountNo:'Account number',ifsc:'IFSC code',upi:'UPI ID'}).map(([k,l])=>field(l,'set-'+k,db.settings[k])).join('')}</div></section><section class="panel"><h2>Default terms</h2><div class="grid">${['quoteTerms','invoiceTerms'].map(k=>`<div><label for="set-${k}">${k==='quoteTerms'?'Quotation':'Invoice'}</label><textarea id="set-${k}" style="min-height:180px">${esc(db.settings[k])}</textarea></div>`).join('')}</div></section><section class="panel"><h2>Data & backups</h2><p class="sub">Documents are stored only in this browser on this device. Clearing browser data removes them. Export a backup to keep a separate copy or move your records to another browser.</p><div class="actions"><button onclick="backup()">Export backup</button><button onclick="document.getElementById('restore').click()">Restore backup</button></div><p class="hint">Backups contain client and payment information. Keep them in a private location. Restore replaces the current records after confirmation.</p></section></div>`}
function saveSettings(){let s=structuredClone(db.settings);Object.keys(s).forEach(k=>{let e=document.getElementById('set-'+k);if(e)s[k]=e.value});if(!s.name.trim()||!Number.isFinite(+s.tax)||+s.tax<0||+s.tax>100){toast('Enter a business name and a tax rate between 0 and 100.');return}let old=db.settings;db.settings=s;if(persist())toast('Settings saved');else db.settings=old}
function backup(){let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Erics-Designs-Backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validateBackup(x){const safeId=v=>typeof v==='string'&&/^[a-zA-Z0-9-]+$/.test(v);if(x&&Array.isArray(x.documents)&&x.documents.some(d=>!safeId(d.id)||!['Draft','Sent','Accepted','Declined','Cancelled'].includes(d.status)))throw Error('Invalid document IDs or statuses.');if(x&&Array.isArray(x.clients)&&x.clients.some(c=>!safeId(c.id)))throw Error('Invalid client IDs.');if(x&&Array.isArray(x.services)&&x.services.some(c=>!safeId(c.id)))throw Error('Invalid service IDs.');if(!x||![1,2].includes(x.version)||!x.settings||!Array.isArray(x.documents)||!Array.isArray(x.clients)||!Array.isArray(x.services))throw Error('Invalid backup format.');if(!Object.keys(defaults.settings).every(k=>typeof x.settings[k]==='string'||k==='tax'&&Number.isFinite(x.settings[k])))throw Error('Invalid business settings.');for(let d of x.documents){if(!d||!['Invoice','Quotation','Proforma'].includes(d.type)||typeof d.id!=='string'||typeof d.number!=='string'||typeof d.date!=='string'||typeof d.due!=='string'||typeof d.updated!=='string'||typeof d.terms!=='string'||typeof d.status!=='string'||!d.client||typeof d.client.name!=='string'||!Array.isArray(d.items)||!Array.isArray(d.payments)||!Number.isFinite(+d.tax)||!Number.isFinite(+d.discount))throw Error('Invalid document records.');for(let i of d.items)if(typeof i.name!=='string'||!Number.isFinite(+i.qty)||+i.qty<=0||!Number.isFinite(+i.rate)||+i.rate<0)throw Error('Invalid service values.');for(let p of d.payments)if(!Number.isFinite(+p.amount)||+p.amount<=0||typeof p.date!=='string')throw Error('Invalid payments.')}for(let s of x.services)if(typeof s.id!=='string'||typeof s.name!=='string'||typeof s.description!=='string'||!Number.isFinite(+s.rate)||+s.rate<0)throw Error('Invalid catalog.');for(let c of x.clients)if(typeof c.id!=='string'||typeof c.name!=='string')throw Error('Invalid clients.');if(new Set(x.documents.map(d=>d.id)).size!==x.documents.length||new Set(x.documents.map(d=>d.number)).size!==x.documents.length)throw Error('Duplicate documents in backup.');return x}
document.getElementById('restore').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>15000000)throw Error('Backup is too large.');let x=validateBackup(JSON.parse(await file.text()));if(!confirm(`Replace current data with ${x.documents.length} documents and ${x.clients.length} clients? Export a backup first if needed.`))return;let old=db;db=x;if(!persist()){db=old;return}render();toast('Backup restored')}catch(err){toast(err.message||'Unable to restore this file.')}finally{e.target.value=''}};
window.addEventListener('beforeunload',e=>{if(draft){e.preventDefault();e.returnValue=''}});window.addEventListener('storage',e=>{if(e.key===KEY)toast('Records changed in another tab. Reload before editing to avoid overwriting changes.')});render();
